package com.retailflow.pos.customer;
import com.retailflow.pos.common.ApiResponse;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/customers") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class CustomerController{private final CustomerService s;public CustomerController(CustomerService s){this.s=s;}@GetMapping public ApiResponse<?>list(){return ApiResponse.ok(s.list());}@GetMapping("/{id}")public ApiResponse<?>get(@PathVariable String id){return ApiResponse.ok(s.get(id));}@PostMapping public ApiResponse<?>create(@RequestBody Customer c){return ApiResponse.ok(s.save(c));}@PutMapping("/{id}")public ApiResponse<?>update(@PathVariable String id,@RequestBody Customer c){c.setId(id);return ApiResponse.ok(s.save(c));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable String id){s.delete(id);return ApiResponse.ok(null);}@GetMapping("/{id}/invoices")public ApiResponse<?>invoices(@PathVariable String id){return ApiResponse.ok(s.invoices(id));}}
